const i = $.input;
const params = {};
const page = Math.max(1, Math.min(500, i.page || 1));
const perPage = Math.max(1, Math.min(100, i.perPage || 25));
params.page = String(page);
params.per_page = String(perPage);

if (i.name) params.q_organization_name = i.name;
if (i.domains && i.domains.length) {
  i.domains.forEach((d, idx) => { params['q_organization_domains_list[' + idx + ']'] = d; });
}
if (i.locations && i.locations.length) {
  i.locations.forEach((l, idx) => { params['organization_locations[' + idx + ']'] = l; });
}
if (i.excludeLocations && i.excludeLocations.length) {
  i.excludeLocations.forEach((l, idx) => { params['organization_not_locations[' + idx + ']'] = l; });
}
if (i.employeeRanges && i.employeeRanges.length) {
  i.employeeRanges.forEach((r, idx) => { params['organization_num_employees_ranges[' + idx + ']'] = r; });
}
if (i.revenueMin != null) params['revenue_range[min]'] = String(i.revenueMin);
if (i.revenueMax != null) params['revenue_range[max]'] = String(i.revenueMax);
if (i.technologies && i.technologies.length) {
  i.technologies.forEach((t, idx) => { params['currently_using_any_of_technology_uids[' + idx + ']'] = t; });
}
if (i.keywords && i.keywords.length) {
  i.keywords.forEach((k, idx) => { params['q_organization_keyword_tags[' + idx + ']'] = k; });
}

return { params, page, perPage };

const resp = $.steps.searchOrgs.response || {};
const orgs = (resp.organizations || []).map(o => ({
  id: o.id,
  name: o.name,
  domain: o.primary_domain,
  website: o.website_url,
  linkedin: o.linkedin_url,
  phone: o.phone,
  foundedYear: o.founded_year,
  alexaRanking: o.alexa_ranking
}));

const pagination = resp.pagination || {};
const totalEntries = pagination.total_entries || 0;
const page = $.steps.buildParams.output.page;
const perPage = $.steps.buildParams.output.perPage;

return {
  organizations: orgs,
  totalEntries,
  page,
  perPage,
  totalPages: pagination.total_pages || 0,
  count: orgs.length,
  summary: totalEntries > 0
    ? `Found ${totalEntries.toLocaleString()} organizations (showing page ${page}, ${orgs.length} results)`
    : 'No organizations matched your search criteria'
};
